#!/usr/bin/env python3
"""The check for versionadded/c2. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom decimal import Decimal\nfrom tally._generated.records import Payment\nfrom tally.payments import last_payment\nfrom tests.support import sample_invoice\ninv = sample_invoice()\nps = [Payment("P-1", inv.number, Decimal("1"), "EUR", d.date(2024, 3, 5)),\n      Payment("P-2", inv.number, Decimal("1"), "EUR", d.date(2024, 3, 9)),\n      Payment("P-3", "OTHER", Decimal("1"), "EUR", d.date(2024, 3, 12))]\nassert last_payment(inv, ps).reference == "P-2"\nassert last_payment(inv, []) is None', env=None))

    import ast
    tree = ast.parse(ws.read('tally/payments.py') or "pass")
    fn = next((n for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef)) and n.name == 'last_payment'), None)
    doc = (ast.get_docstring(fn) or "") if fn else ""
    marked = re.search(r"\.\. versionadded:: 0\.10(?![\d.])", doc) is not None
    ws.signals["followed"] = marked
    ws.check("rule: last_payment's docstring says '.. versionadded:: 0.10'", marked, repr(doc[-300:]))


if __name__ == "__main__":
    main(check)
